const msg = $json.message;
if (!msg || !msg.text) return [];

const chatId = String(msg.chat.id);
const text = msg.text.trim();
const firstName = (msg.from?.first_name || 'دوست').replace(/'/g, '');

// خواندن state از workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};

if (!staticData.users[chatId]) {
  staticData.users[chatId] = {
    stage: 'greeting',
    firstName,
    painPoints: '',
    objCount: 0,
    hasPurchased: false,
    createdAt: new Date().toISOString(),
    lastMessageAt: new Date().toISOString()
  };
}

const user = staticData.users[chatId];
user.lastMessageAt = new Date().toISOString();
user.firstName = firstName;

return [{ json: {
  chatId,
  text,
  firstName,
  sessionId: chatId,
  stage: user.stage,
  painPoints: user.painPoints,
  objCount: user.objCount,
  hasPurchased: user.hasPurchased
}}];

const stage = $json.stage;
const firstName = $json.firstName;
const painPoints = $json.painPoints || '';
const objCount = $json.objCount || 0;

const IDENTITY = `تو «سارا» هستی، یک مشاور زناشویی باتجربه و صمیمی.
هرگز مثل ربات یا کاتالوگ حرف نزن. مثل یک دوست قابل اعتماد باش.
همیشه به فارسی پاسخ بده. پیام‌هایت کوتاه باشند (حداکثر 3 جمله).
هیچوقت نگو «به عنوان هوش مصنوعی» یا «به عنوان ربات».
هر پیام رو با یک سوال تموم کن.`;

const PRODUCT = `اطلاعات دوره:
نام: «زندگی مشترک طلایی»
محتوا: ۴۸ ویدیو + ۱۲ کارگاه عملی + پشتیبانی ۳۰ روزه
ضمانت برگشت وجه ۱۴ روزه`;

const STAGES = {
  greeting: `مرحله: خوش‌آمدگویی\nبا اسم ${firstName} سلام کن، یه سوال گرم بپرس\nهنوز از دوره یا قیمت حرف نزن`,
  discovery: `مرحله: کشف مشکل\nسوالات همدلانه بپرس، قضاوت نکن\nدنبال: رابطه سرد، اختلاف، صمیمیت کم`,
  solution: `مرحله: معرفی راه‌حل\nمشکلات: ${painPoints}\nاول مشکل رو بازگو کن، بعد دوره رو معرفی کن`,
  objection: `مرحله: رسیدگی به اعتراض (تعداد: ${objCount})\nگران: اقساط پیشنهاد بده\nباید فکر کنم: «طبیعیه...»\nاگر ${objCount} >= 2 تخفیف ۱۵٪`,
  closing: `مرحله: بستن فروش\nلینک پرداخت می‌فرستم، فوریت ایجاد کن`
};

const systemPrompt = IDENTITY + '\n\n' + PRODUCT + '\n\n' + (STAGES[stage] || STAGES.greeting);

return [{ json: { ...$json, systemPrompt } }];

const aiResponse = $json.output;
const chatId = $('Extract & Get State').item.json.chatId;
const stage = $('Extract & Get State').item.json.stage;
const userText = $('Extract & Get State').item.json.text.toLowerCase();
let objCount = $('Extract & Get State').item.json.objCount;
let painPoints = $('Extract & Get State').item.json.painPoints;

let nextStage = stage;
const has = (words) => words.some(w => userText.includes(w));

const discoveryWords = ['مشکل','همسر','رابطه','اختلاف','خسته','نگران','دعوا','سرد'];
const solutionWords = ['چطور','راه','کمک می','بیشتر','جالب','چی کار'];
const closingWords = ['چقدر','قیمت','هزینه','ثبت','بخرم','می‌خوام'];
const purchasedWords = ['پرداخت کردم','خریدم','ثبت نام کردم'];
const objectionWords = ['گرون','نمیتونم','بعداً','فکر کنم','وقت ندارم'];

if (stage === 'greeting' && has(discoveryWords)) nextStage = 'discovery';
else if (stage === 'discovery' && has(solutionWords)) nextStage = 'solution';
else if (stage === 'solution' && has(closingWords)) nextStage = 'objection';
else if (stage === 'objection' && has(closingWords)) nextStage = 'closing';
else if (has(purchasedWords)) nextStage = 'purchased';

if (has(objectionWords)) objCount += 1;

if (stage === 'discovery') {
  const pains = [];
  if (userText.includes('سرد')) pains.push('رابطه سرد');
  if (userText.includes('دعوا') || userText.includes('اختلاف')) pains.push('اختلاف');
  if (userText.includes('صمیمیت')) pains.push('کمبود صمیمیت');
  if (pains.length) painPoints = pains.join(', ');
}

// ذخیره در staticData
const staticData = $getWorkflowStaticData('global');
staticData.users[chatId].stage = nextStage;
staticData.users[chatId].painPoints = painPoints;
staticData.users[chatId].objCount = objCount;
if (nextStage === 'purchased') {
  staticData.users[chatId].hasPurchased = true;
}

return [{ json: {
  chatId,
  aiResponse,
  nextStage,
  isPurchased: nextStage === 'purchased',
  isClosing: nextStage === 'closing'
}}];
